async function loadUser(id: string): Promise<any> {
  try {
    const r = await fetch('/api/users/' + id);
    if (!r.ok) throw new Error('bad status ' + r.status);
    const u = await r.json();
    const r2 = await fetch('/api/orgs/' + u.orgId);
    if (!r2.ok) throw new Error('bad status ' + r2.status);
    const o = await r2.json();
    u.org = o;
    return u;
  } catch (e) {
    throw e;
  }
}

async function loadUsers(ids: string[]): Promise<any[]> {
  const out: any[] = [];
  const promises = ids.map(async (id, i) => {
    try {
      out[i] = await loadUser(id);
    } catch (e) {
      throw e;
    }
  });
  await Promise.all(promises);
  return out;
}

module.exports = { loadUser, loadUsers };
